local Players = game:GetService("Players")

-- Extra info we keep while each player is here
local playerInfo = {}

Players.PlayerAdded:Connect(function(player)
	playerInfo[player] = { coinsCollected = 0 }

	-- When a character is removed, destroy it so its connections are freed
	player.CharacterRemoving:Connect(function(character)
		task.defer(character.Destroy, character)
	end)
end)

Players.PlayerRemoving:Connect(function(player)
	-- Forget our table entry for this player
	playerInfo[player] = nil
	-- Destroy the Player object so its connections are freed
	task.defer(player.Destroy, player)
end)
